import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import {
  CERTIFICATE_MODE_UNSUPPORTED,
  verifyBundle,
  type ClaimResult,
} from "../src/bundle.js";
import {
  CATEGORY_COVERAGE_PROPERTIES,
  categoryCoverageSigningInput,
} from "../src/category-coverage.js";

// Evidence Bundle -02 against vectors/bundle/non-record-leaves,
// vectors/bundle/certificate-mode and vectors/bundle/category-coverage
// (generated by python/scripts/generate_bundle_02_vectors.py), compared as
// python/tests/test_bundle_02_vectors.py and
// python/tests/test_bundle_certificate_modes.py do.
type Obj = Record<string, unknown>;
type Case = {
  id: string;
  options: Obj;
  bundle: unknown;
  expect: Obj;
};
const load = (directory: string): Case[] => {
  const dir = resolve(process.cwd(), "..", "vectors", "bundle", directory);
  const cases = (
    JSON.parse(readFileSync(resolve(dir, "vectors.json"), "utf8")) as {
      cases: Case[];
    }
  ).cases;
  const manifest = JSON.parse(
    readFileSync(resolve(dir, "manifest.json"), "utf8"),
  ) as { case_count: number };
  expect(cases).toHaveLength(manifest.case_count);
  return cases;
};
const bundleOf = (directory: string, id: string): Obj =>
  structuredClone(load(directory).find((c) => c.id === id)!.bundle) as Obj;

const observed = (
  result: Awaited<ReturnType<typeof verifyBundle>> & {
    strict: NonNullable<Awaited<ReturnType<typeof verifyBundle>>["strict"]>;
  },
): Obj => ({
  verdict: result.strict.verdict,
  kind_ok: result.strict.kindOk,
  claims: result.strict.claims.map(({ name, status, findings }) => ({
    name,
    status,
    findings,
  })),
  witnesses:
    result.strict.witnesses === null
      ? null
      : {
          status: result.strict.witnesses.status,
          findings: result.strict.witnesses.findings,
          receipts: [],
        },
  records: result.strict.records.map((r) => ({
    capsule_id: r.capsuleId,
    identity_ok: r.identityOk,
    signature: r.signature,
    key_id: r.keyId,
    seq: r.seq,
  })),
  checkpoint_authenticated: result.strict.checkpointAuthenticated,
  signer_matches_checkpoint: result.strict.signerMatchesCheckpoint,
});

describe("Bundle -02 certificate vectors", () => {
  for (const directory of ["non-record-leaves", "certificate-mode"])
    it.each(load(directory).map((c) => [`${directory}/${c.id}`, c] as const))(
      "%s",
      async (_id, testCase) => {
        expect(testCase.options).toEqual({
          require_signature: false,
          witness_directory: false,
        });
        const result = await verifyBundle(testCase.bundle, { strict: true });
        expect(observed(result)).toEqual({ kind_ok: true, ...testCase.expect });
      },
    );
});

const coverageOptions = (options: Obj) => ({
  categorySets: options.category_sets as Record<string, string[]> | null,
  categoryRequest:
    typeof options.category_request === "string"
      ? new TextEncoder().encode(options.category_request)
      : null,
  recordCategories: options.record_categories as Record<
    string,
    string | null
  > | null,
});

describe("Bundle -02 category_coverage vectors", () => {
  it.each(load("category-coverage").map((c) => [c.id, c] as const))(
    "%s",
    async (_id, testCase) => {
      const result = await verifyBundle(testCase.bundle, {
        strict: true,
        ...coverageOptions(testCase.options),
      });
      expect({
        verdict: result.strict.verdict,
        category_coverage: result.categoryCoverage,
      }).toEqual(testCase.expect);
      // The claims are the base Bundle's: the member changes none of them.
      expect(result.strict.claims.every((c) => c.status === "pass")).toBe(true);
      if (result.categoryCoverage !== null)
        expect(Object.keys(result.categoryCoverage)).toEqual(
          CATEGORY_COVERAGE_PROPERTIES,
        );
    },
  );

  it("is reported in plain mode, without a verdict", async () => {
    const testCase = load("category-coverage").find(
      (c) => c.id === "neg-consistency-absent-with-record",
    )!;
    const result = await verifyBundle(
      testCase.bundle,
      coverageOptions(testCase.options),
    );
    expect(result.strict).toBeUndefined();
    expect(result.categoryCoverage).toEqual(testCase.expect.category_coverage);
  });

  it("a non-canonical root fails the signature and never throws", async () => {
    for (const root of [1.5, 2 ** 60]) {
      const bundle = bundleOf("category-coverage", "pos-all-six-statuses");
      bundle.root = root;
      const plain = await verifyBundle(bundle);
      expect(plain.categoryCoverage!.category_coverage_signature).toBe("FAIL");
      const strict = await verifyBundle(bundle, { strict: true });
      expect(strict.categoryCoverage!.category_coverage_signature).toBe("FAIL");
      expect(strict.strict.verdict).toBe("INVALID");
    }
  });

  it("an ignored member does not fail the form", async () => {
    const bundle = bundleOf("category-coverage", "unsigned-member");
    (bundle.category_coverage as Obj)["x-note"] = { weight: 0.5 };
    expect(
      (await verifyBundle(bundle)).categoryCoverage!.category_coverage_form,
    ).toBe("PASS");
  });

  it("reads the request strictly", async () => {
    const bundle = bundleOf("category-coverage", "request-without-categories");
    const request = async (octets: Uint8Array | string) =>
      (
        await verifyBundle(bundle, {
          categoryRequest:
            typeof octets === "string"
              ? new TextEncoder().encode(octets)
              : octets,
        })
      ).categoryCoverage!.category_coverage_request;
    for (const text of [
      '{"categories": NaN}',
      '{"categories": Infinity}',
      '{"a": {"b": 1, "b": 2}}',
      '[{"x": 1, "x": 1}]',
      '{"categories": {"set": "example-set", "names": ["messages"]}} {}',
      "[]",
      "",
      '{"categories": {"set": "example-set", "names": ["messages", "messages"]}}',
      '{"categories": {"set": "example-set", "names": []}}',
      '{"categories": {"set": 1, "names": ["messages"]}}',
    ])
      expect(await request(text), text).toBe("NOT_CHECKED");
    expect(await request(Uint8Array.from([0x7b, 0xff, 0x7d]))).toBe(
      "NOT_CHECKED",
    );
    // A byte order mark is not JSON, as Python and Go read it.
    expect(
      await request(
        Uint8Array.from([0xef, 0xbb, 0xbf, ...new TextEncoder().encode("{}")]),
      ),
    ).toBe("NOT_CHECKED");
    expect(await request("{}")).toBe("NOT_PRESENT");
    // An unpaired surrogate escape is refused wherever it is (I-JSON); a
    // pair, and escapes that only look like one, are read.
    for (const text of [
      String.raw`{"x": "\ud800"}`,
      String.raw`{"x": "\udc00"}`,
      String.raw`{"\ud800": 1}`,
      String.raw`["a\ud800b"]`,
      String.raw`{"x": "\ud800\u0041"}`,
      String.raw`{"x": "\ud800\ud800"}`,
      String.raw`{"x": "\udc00\ud800"}`,
    ])
      expect(await request(text), text).toBe("NOT_CHECKED");
    for (const text of [
      String.raw`{"x": "\ud83d\ude00"}`,
      String.raw`{"x": "\\ud800"}`,
      String.raw`{"x": "\"\ud83d\ude00"}`,
      String.raw`{"x": "\u00e9"}`,
    ])
      expect(await request(text), text).toBe("NOT_PRESENT");
    // The same member name in two objects is no repeat.
    expect(
      await request('{"a": {"x": 1}, "b": {"x": [{"x": 2}]}, "x": 3}'),
    ).toBe("NOT_PRESENT");
  });

  it("refuses a small-order signer key", async () => {
    // The identity point: it "verifies" a signature whose R is the identity
    // and S is zero over any message, in a verifier with no small-order check.
    const bundle = bundleOf("category-coverage", "pos-no-inputs");
    const member = bundle.category_coverage as Obj;
    member.signer = { key_id: `01${"00".repeat(31)}` };
    member.signature = `01${"00".repeat(63)}`;
    expect(
      (await verifyBundle(bundle)).categoryCoverage!
        .category_coverage_signature,
    ).toBe("FAIL");
  });
});

const plainClaims = async (bundle: unknown): Promise<ClaimResult[]> => {
  const result = await verifyBundle(bundle);
  expect(result.strict).toBeUndefined();
  return [result.intervalCoverage, result.perRecordMembership];
};
const claim = (status: string, ...findings: string[]) => ({
  status,
  findings,
});

describe("Bundle -02 certificate modes, plain", () => {
  const selected = () =>
    bundleOf("certificate-mode", "incomplete-producer-selected-padded-log");
  const notCheckable = claim("withheld", "selection_not_checkable");

  it("a producer-selected Bundle is not a failure", async () => {
    expect(await plainClaims(selected())).toEqual([
      notCheckable,
      claim("pass"),
    ]);
  });

  it("without cose it is qualified; a bad cose fails", async () => {
    const unsigned = selected();
    delete (unsigned.checkpoint as Obj).cose;
    expect((await plainClaims(unsigned))[1]).toEqual(
      claim("pass", "checkpoint_unverified"),
    );
    const bad = selected();
    const cose = (bad.checkpoint as Obj).cose as string;
    (bad.checkpoint as Obj).cose = `${cose.slice(0, -4)}AAAA`;
    expect((await plainClaims(bad))[1]).toEqual(
      claim("fail", "checkpoint_authentication_invalid"),
    );
  });

  it("a tampered proof fails", async () => {
    const bundle = bundleOf(
      "certificate-mode",
      "neg-producer-selected-padded-log-tampered",
    );
    expect((await plainClaims(bundle))[1]).toEqual(
      claim("fail", `membership_proof_invalid:${bundle.root as string}`),
    );
  });

  it("the root and log_id must be the checkpoint's", async () => {
    const otherRoot = selected();
    delete (otherRoot.checkpoint as Obj).cose;
    (otherRoot.checkpoint as Obj).root = "00".repeat(32);
    expect((await plainClaims(otherRoot))[1]).toEqual(
      claim("fail", "completeness_certificate_invalid"),
    );
    const noLogId = selected();
    delete (noLogId.checkpoint as Obj).cose;
    delete (noLogId.completeness_certificate as Obj).log_id;
    expect((await plainClaims(noLogId))[1]).toEqual(
      claim("fail", "completeness_certificate_invalid"),
    );
    const objectRoot = selected();
    (objectRoot.checkpoint as Obj).root = {};
    (objectRoot.completeness_certificate as Obj).range_root = {};
    expect((await plainClaims(objectRoot))[1]).toEqual(
      claim("fail", "completeness_certificate_invalid"),
    );
  });

  it.each([["x-sampled"], [7], [""], [{ mode: "producer-selected" }], [null]])(
    "selection %j is an unsupported mode",
    async (value) => {
      const bundle = selected();
      (bundle.completeness as Obj).selection = value;
      const unsupported = claim("withheld", CERTIFICATE_MODE_UNSUPPORTED);
      expect(await plainClaims(bundle)).toEqual([unsupported, unsupported]);
    },
  );

  it("an absent selection is a range; a null one is not", async () => {
    const bundle = bundleOf(
      "certificate-mode",
      "incomplete-certificate-mode-null",
    );
    const unsupported = claim("withheld", CERTIFICATE_MODE_UNSUPPORTED);
    expect(await plainClaims(bundle)).toEqual([unsupported, unsupported]);
    delete (bundle.completeness as Obj).selection;
    expect(await plainClaims(bundle)).toEqual([claim("pass"), claim("pass")]);
  });

  it("a padded range passes and an unknown type withholds", async () => {
    expect(
      await plainClaims(bundleOf("non-record-leaves", "pos-padded-whole-log")),
    ).toEqual([claim("pass"), claim("pass")]);
    const unknown = bundleOf(
      "non-record-leaves",
      "incomplete-unknown-leaf-type",
    );
    expect((await plainClaims(unknown))[1]).toEqual(
      claim("withheld", "non_record_leaf_type_unsupported:20"),
    );
    delete (unknown.checkpoint as Obj).cose;
    expect((await plainClaims(unknown))[1]).toEqual(
      claim(
        "withheld",
        "non_record_leaf_type_unsupported:20",
        "checkpoint_unverified",
      ),
    );
  });

  it("the member on a producer-selected Bundle is invalid, signed or not", async () => {
    const bundle = bundleOf(
      "non-record-leaves",
      "neg-non-record-leaves-on-producer-selected",
    );
    expect((await plainClaims(bundle))[1]).toEqual(
      claim("fail", "completeness_certificate_invalid"),
    );
    delete (bundle.checkpoint as Obj).cose;
    const result = await verifyBundle(bundle, { strict: true });
    expect(result.perRecordMembership).toEqual(
      claim("fail", "completeness_certificate_invalid"),
    );
    expect(result.strict.verdict).toBe("INVALID");
  });

  it("unknown certificate members are ignored", async () => {
    const bundle = bundleOf("non-record-leaves", "pos-padded-whole-log");
    const certificate = bundle.completeness_certificate as Obj;
    certificate["x-note"] = { anything: [1, 2] };
    (certificate.non_record_leaves as Obj[])[0]!["x-note"] = "ignored";
    expect((await verifyBundle(bundle, { strict: true })).strict.verdict).toBe(
      "VALID",
    );
  });
});

// Cases the vectors leave out, each pinned to what the Python reference
// reports for the same edit.
describe("Bundle -02 edges", () => {
  it("a non-record leaf below the interval is a seq_invalid", async () => {
    const bundle = bundleOf("non-record-leaves", "pos-padded-suffix");
    const leaves = (bundle.completeness_certificate as Obj)
      .non_record_leaves as Obj[];
    leaves.push({ seq: 5, content: leaves[0]!.content });
    const result = await verifyBundle(bundle, { strict: true });
    expect(result.perRecordMembership).toEqual(
      claim("fail", "non_record_leaf_seq_invalid:56"),
    );
  });

  it("a fifth content member is malformed, whatever its name", async () => {
    const bundle = bundleOf("non-record-leaves", "pos-padded-whole-log");
    const content = (
      (bundle.completeness_certificate as Obj).non_record_leaves as Obj[]
    )[0]!.content as Obj;
    content.zz = 1; // sorts after every padding member
    const result = await verifyBundle(bundle, { strict: true });
    expect(result.perRecordMembership).toEqual(
      claim("fail", "non_record_leaf_malformed:6"),
    );
  });

  it("a record_type that is not a string is malformed", async () => {
    const bundle = bundleOf("non-record-leaves", "pos-padded-whole-log");
    const content = (
      (bundle.completeness_certificate as Obj).non_record_leaves as Obj[]
    )[0]!.content as Obj;
    content.record_type = 7;
    const result = await verifyBundle(bundle, { strict: true });
    expect(result.perRecordMembership).toEqual(
      claim("fail", "non_record_leaf_malformed:6"),
    );
  });

  it("a padding capsule_id in uppercase is malformed", async () => {
    const bundle = bundleOf("non-record-leaves", "pos-padded-whole-log");
    const content = (
      (bundle.completeness_certificate as Obj).non_record_leaves as Obj[]
    )[0]!.content as Obj;
    content.capsule_id = (content.capsule_id as string).toUpperCase();
    const result = await verifyBundle(bundle, { strict: true });
    expect(result.perRecordMembership).toEqual(
      claim("fail", "non_record_leaf_malformed:6"),
    );
  });

  it.each<[string, (member: Obj) => void]>([
    ["empty set", (m) => (m.set = "")],
    [
      "empty name",
      (m) => ((m.categories as Obj)[""] = { status: "AVAILABLE" }),
    ],
    [
      "policy_uri not a string",
      (m) =>
        (((m.categories as Obj).messages as Obj).policy_uri = [
          "https://example.com/policy",
        ]),
    ],
    [
      "key_id in uppercase",
      (m) =>
        ((m.signer as Obj).key_id = (
          (m.signer as Obj).key_id as string
        ).toUpperCase()),
    ],
    [
      "signature one digit short",
      (m) => (m.signature = (m.signature as string).slice(1)),
    ],
    ["signature without signer", (m) => delete m.signer],
  ])("the form fails: %s", async (_name, edit) => {
    const bundle = bundleOf("category-coverage", "pos-no-inputs");
    edit(bundle.category_coverage as Obj);
    expect(
      (await verifyBundle(bundle)).categoryCoverage!.category_coverage_form,
    ).toBe("FAIL");
  });

  it("a requested name that is not UTF-8 is not read", async () => {
    const bundle = bundleOf("category-coverage", "request-without-categories");
    const request = async (octets: Uint8Array) =>
      (await verifyBundle(bundle, { categoryRequest: octets }))
        .categoryCoverage!.category_coverage_request;
    const encode = (text: string) => new TextEncoder().encode(text);
    expect(
      await request(
        Uint8Array.from([
          ...encode('{"categories": {"set": "example-set", "names": ["'),
          0xff,
          ...encode('"]}}'),
        ]),
      ),
    ).toBe("NOT_CHECKED");
    expect(
      await request(
        encode('{"categories": {"set": "example-set", "names": ["nope"]}}'),
      ),
    ).toBe("FAIL");
  });
});

describe("Bundle -02 category_coverage signature without a root", () => {
  it("signs over a null root, as Python and Go read an absent one", async () => {
    const bundle = bundleOf("category-coverage", "unsigned-member");
    delete bundle.root;
    const member = bundle.category_coverage as Obj;
    const pair = (await crypto.subtle.generateKey({ name: "Ed25519" }, true, [
      "sign",
      "verify",
    ])) as CryptoKeyPair;
    const raw = new Uint8Array(
      await crypto.subtle.exportKey("raw", pair.publicKey),
    );
    member.signer = { key_id: Buffer.from(raw).toString("hex") };
    member.signature = "00".repeat(64);
    const signature = await crypto.subtle.sign(
      { name: "Ed25519" },
      pair.privateKey,
      categoryCoverageSigningInput(member, null) as BufferSource,
    );
    member.signature = Buffer.from(signature).toString("hex");
    expect(
      (await verifyBundle(bundle)).categoryCoverage!
        .category_coverage_signature,
    ).toBe("PASS");
  });
});
